'  IS'||wwv_flow.LF||
'      l_year        NUMBER := EXTRACT(YEAR FROM SYSDATE);';
wwv_flow_imp.g_varchar2_table(5) := ''||wwv_flow.LF||
'      l_remaining   TMS_LEAVE_BALANCES.REMAINING%TYPE;'||wwv_flow.LF||
'      l_entitlement TMS_LEAVE_TYPES.MAX_DAYS';
wwv_flow_imp.g_varchar2_table(6) := '_PER_YEAR%TYPE;'||wwv_flow.LF||
