wwv_flow_imp.g_varchar2_table(7) := 'd IS NULL THEN'||wwv_flow.LF||
'          RETURN NULL;'||wwv_flow.LF||
'      END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'      -- First try the current balance table.'||wwv_flow.LF||
' ';
wwv_flow_imp.g_varchar2_table(8) := '     BEGIN'||wwv_flow.LF||
