'      END;'||wwv_flow.LF||
''||wwv_flow.LF||
'      -- Fallback: calculate from entitlem';
wwv_flow_imp.g_varchar2_table(12) := 'ent minus approved leave requests.'||wwv_flow.LF||
'      BEGIN'||wwv_flow.LF||
'          SELECT lt.max_days_per_year'||wwv_flow.LF||
